// ── Edit your business details, then click Test workflow ──
return [{ json: {
  businessName: 'Bright Smile Dental',            // shown in every message
  bookingUrl:   'https://YOUR-BOOKING-LINK',      // where clients rebook
  reviewUrl:    'https://YOUR-GOOGLE-REVIEW-LINK', // your Google review link
  reminderDaysBefore: 1                            // send reminder N days before
} }];

// Decide what to do with each appointment row.
const cfg = $('Configuration').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const todayStr = today.toISOString().slice(0,10);
const out = [];
for (const row of $input.all()) {
  const j = row.json;
  const status = String(j.Status || '').trim().toLowerCase();
  const dateStr = String(j.AppointmentDate || '').slice(0, 10);
  if (!j.Email || !dateStr) continue;
  const appt = new Date(dateStr + 'T00:00:00');
  const days = Math.round((appt - today) / 86400000);
  let action = 'skip', newStatus = status;
  if (status === 'new')                                     { action='confirm';  newStatus='confirmed'; }
  else if (status === 'confirmed' && days === cfg.reminderDaysBefore) { action='remind';   newStatus='reminded'; }
  else if (status === 'no-show')                            { action='winback';  newStatus='winback-sent'; }
  else if (status === 'completed' && days === -1)           { action='review';   newStatus='review-requested'; }
  if (action === 'skip') continue;
  out.push({ json: {
    AppointmentID: j.AppointmentID, Name: j.Name || 'there', Email: j.Email,
    AppointmentDate: j.AppointmentDate, action, newStatus, todayStr
  }});
}
return out;
